import{_ as a,o as d,c as n,a2 as t}from"./chunks/framework.B2iPdV6-.js";const h=JSON.parse('{"title":"架构","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/architecture.md","filePath":"zh/guide/architecture.md","lastUpdated":1790923704000}'),o={name:"zh/guide/architecture.md"};function s(c,e,r,i,p,l){return d(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to &quot;架构&quot;">​</a></h1><p>NeoFlux 把一个 UI 应用拆成两个独立线程层，二者仅通过一条无锁队列通信。 应用层负责全部业务逻辑与布局；渲染层持有 GPU/GL 上下文，把录制好的命令变成像素。</p><h2 id="两层划分" tabindex="-1">两层划分 <a class="header-anchor" href="#两层划分" aria-label="Permalink to &quot;两层划分&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+------------------ 应用线程（Application::Run）-------------------+</span></span>
<span class="line"><span>|                                                                  |</span></span>
<span class="line"><span>|  EventLoop（--target_fps）                                       |</span></span>
<span class="line"><span>|    |  OnFrame()                                                 |</span></span>
<span class="line"><span>|    |   1. PollEvents() + ShouldClose()                          |</span></span>
<span class="line"><span>|    |   2. BuildDirtyWidgets()    重建脏的 StatefulWidget 子树     |</span></span>
<span class="line"><span>|    |   3. LayoutWidgetTree()     在 widget 树上跑 Taitank flexbox |</span></span>
<span class="line"><span>|    |   4. PaintAndSubmit()      录制 kBeginFrame .. draw* .. kEndFrame |</span></span>
<span class="line"><span>|    |                          |                                 |</span></span>
<span class="line"><span>|    |                          |  RenderLayer::Submit(commands, n) |</span></span>
<span class="line"><span>|    |                          v                                 |</span></span>
<span class="line"><span>|    |                SpscRingQueue&lt;RenderCommand&gt;  &lt;-- 1 生产者 1 消费者 |</span></span>
<span class="line"><span>+----|--------------------------|-----------------------------------+</span></span>
<span class="line"><span>     |  frame_cv_.notify_one   |</span></span>
<span class="line"><span>+----|--------------------------v-----------------------------------+</span></span>
<span class="line"><span>|    |        渲染线程（RenderLayer::RenderLoop）                    |</span></span>
<span class="line"><span>|    |           等待 frame_cv_，排空队列，按 Begin/End 边界绘制      |</span></span>
<span class="line"><span>|    |                            |                                 |</span></span>
<span class="line"><span>|    |                            v                                 |</span></span>
<span class="line"><span>|    |                  TgfxRenderer（tgfx，或内置 GL 回退）         |</span></span>
<span class="line"><span>|    |                            |                                 |</span></span>
<span class="line"><span>|    |   桌面：GlfwBridge（GLFW 窗口 + WGL 上下文）-&gt; SwapBuffers() |</span></span>
<span class="line"><span>|    |   移动：平台 Surface（ANativeWindow / CAMetalLayer）         |</span></span>
<span class="line"><span>+----+------------------------------------------------------------+</span></span></code></pre></div><h2 id="应用层-ui-线程" tabindex="-1">应用层（UI 线程） <a class="header-anchor" href="#应用层-ui-线程" aria-label="Permalink to &quot;应用层（UI 线程）&quot;">​</a></h2><p>运行在调用 <code>Application::Run()</code> 的线程上，是唯一允许触碰 widget 对象的线程。</p><ul><li><strong>Widget 树</strong> —— <code>shared_ptr&lt;Widget&gt;</code> 组成的树。有状态 widget 重建子树； 叶子 widget（<code>Text</code>、<code>Button</code>）上报自身固有尺寸。</li><li><strong>Taitank 布局</strong> —— 每个 <code>Widget</code> 持有一个不透明的 <code>taitank::TaitankNode</code>。 <code>PerformLayout(w, h)</code> 对根节点跑 <code>taitank::DoLayout</code>，再把算好的矩形回写到 widget 树。</li><li><strong>事件循环</strong> —— <code>EventLoop</code> 中由条件变量驱动的循环，空闲时睡眠，被 <code>WakeUp()</code>（输入、<code>MarkFrameDirty()</code>、定时器）唤醒。<code>--target_fps</code> 限制最高帧率。</li><li><strong>命令录制</strong> —— 在 <code>PaintAndSubmit()</code> 中，应用把 <code>kBeginFrame</code> 标记、各 widget 的绘制命令、<code>kEndFrame</code> 标记依次追加进 <code>RenderContext</code>。</li></ul><p>只有在确实“脏”的时候才产出一帧：若 <code>frame_dirty_</code> 与 widget 重建都没发生， <code>OnFrame()</code> 直接返回，空闲 CPU 占用接近于零。</p><h2 id="渲染层-渲染线程" tabindex="-1">渲染层（渲染线程） <a class="header-anchor" href="#渲染层-渲染线程" aria-label="Permalink to &quot;渲染层（渲染线程）&quot;">​</a></h2><p><code>RenderLayer::Start()</code> 派生一个专用 <code>std::thread</code> 运行 <code>RenderLoop()</code>。 该线程独占 GL 上下文。</p><ul><li><strong>GL 上下文归属</strong> —— 桌面端上下文由 <code>GlfwBridge</code> 创建。先在主线程短暂 make current，让 OpenGL 加载器（<code>glfwGetProcAddress</code>/WGL）解析函数指针，然后 release， 在渲染线程上重新 acquire，专门负责真正的绘制。</li><li><strong>帧状态机</strong> —— 只有 <code>kBeginFrame</code> 与 <code>kEndFrame</code> 之间的命令才会被执行， 避免渲染线程在应用还在提交命令时就呈现半帧画面。</li><li><strong>后端</strong> —— <code>TgfxRenderer</code> 封装 <code>tgfx</code>。关闭 <code>NEOFLUX_USE_TGFX</code> 时回退到内置 OpenGL 渲染器（shader + VBO + FreeType 字形图集）。<code>--render_backend</code> 默认为 <code>gl</code>（本构建唯一可用后端）；<code>vulkan</code>、<code>cpu</code> 及未知值都是启动期硬错误，而非静默回退到 GL。</li></ul><h2 id="命令如何跨线程" tabindex="-1">命令如何跨线程 <a class="header-anchor" href="#命令如何跨线程" aria-label="Permalink to &quot;命令如何跨线程&quot;">​</a></h2><p>两层不会跨帧直接互相调用渲染代码，而是：</p><ol><li><strong>应用线程</strong>是唯一生产者：<code>RenderLayer::Submit()</code> 对每条录制命令调用 <code>command_queue_.TryPush(cmd)</code>。队列满时本帧多余命令被丢弃（限频警告）。</li><li><code>Submit()</code> 随后置 <code>frame_ready_ = true</code> 并 <code>frame_cv_.notify_one()</code> 唤醒渲染线程。</li><li><strong>渲染线程</strong>是唯一消费者：在 <code>frame_cv_</code> 上等待（最长 16ms），然后 <code>TryPop()</code> 取走所有可用命令并分发给 <code>TgfxRenderer</code>。遇到 <code>kEndFrame</code> 时调用 <code>EndFrame()</code>，桌面端再 <code>GlfwBridge::SwapBuffers()</code>。</li></ol><h3 id="spscringqueue-细节" tabindex="-1">SpscRingQueue 细节 <a class="header-anchor" href="#spscringqueue-细节" aria-label="Permalink to &quot;SpscRingQueue 细节&quot;">​</a></h3><p>定义于 <code>include/neoflux/core/ring_queue.h</code>：</p><table tabindex="0"><thead><tr><th>属性</th><th>值</th></tr></thead><tbody><tr><td>类型</td><td>有界、<strong>单生产者单消费者（SPSC）</strong>、无锁</td></tr><tr><td>容量</td><td>由 <code>--render_queue_capacity</code> 设置（默认 <code>2048</code>），向上取整为 2 的幂</td></tr><tr><td>可用槽位</td><td><code>capacity - 1</code>（保留一个槽位区分满/空）</td></tr><tr><td>索引</td><td><code>head_</code>（生产者）与 <code>tail_</code>（消费者）均 <code>alignas(64)</code>，避免缓存行伪共享</td></tr><tr><td>回绕</td><td>2 的幂容量使回绕可用 <code>&amp; mask_</code> 代替 <code>%</code></td></tr><tr><td>接口</td><td>生产者 <code>TryPush()</code>，消费者 <code>TryPop()</code>，另提供 <code>Empty()</code>/<code>Full()</code>/<code>Size()</code> 快照</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">仅允许一个生产者和一个消费者</p><p>该队列按 SPSC 安全设计，并非 MPMC。切勿从渲染线程 push，或从应用线程 pop。 <code>frame_cv_</code> 条件变量是唯一带互斥锁的握手；队列本身无锁等待。</p></div><h2 id="输入流" tabindex="-1">输入流 <a class="header-anchor" href="#输入流" aria-label="Permalink to &quot;输入流&quot;">​</a></h2><p>指针与滚动事件来自窗口线程的 <code>GlfwBridge</code>，交给 <code>Application</code>：</p><ol><li>把光标坐标从真实（DPI 缩放后的）窗口尺寸缩放到逻辑布局尺寸。</li><li>递归 <code>HitTest()</code>（子节点按“从上到下”顺序测试），并带 hover 命中缓存， 每次布局变化即失效。</li><li>把按下/抬起交给消费了按下事件的 widget，把移动交给 hover（或按下）的 widget， 滚动事件则<strong>沿祖先冒泡</strong>，直到某个 widget 消费它。</li></ol><p><code>pressed_widget_</code> 用 <code>weak_ptr</code> 持有，避免帧之间 widget 树重建造成悬垂指针。 完整事件契约见<a href="./input">输入与事件</a>。</p><h2 id="平台矩阵" tabindex="-1">平台矩阵 <a class="header-anchor" href="#平台矩阵" aria-label="Permalink to &quot;平台矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>窗口</th><th>GL/GL 上下文</th><th>渲染目标</th></tr></thead><tbody><tr><td>Windows / Linux / macOS</td><td><code>GlfwBridge</code>（GLFW）</td><td>WGL / GLX / CGL</td><td>窗口 framebuffer</td></tr><tr><td>Android / iOS</td><td>系统提供的 Surface</td><td>无</td><td><code>ANativeWindow</code> / <code>CAMetalLayer</code></td></tr></tbody></table><p>预处理器选择桥接实现：桌面构建 <code>glfw_bridge.cpp</code>，Android/iOS 构建 <code>mobile_bridge.cpp</code>（<code>NEOFLUX_PLATFORM_DESKTOP</code> 与 <code>NEOFLUX_PLATFORM_MOBILE</code>）。</p>`,25)])])}const g=a(o,[["render",s]]);export{h as __pageData,g as default};
